+		t.Fatalf("forget: %v %v", ok, err)
+	}
+	if after, _, ok := r.f.AgentItem(id); !ok || after != before {
+		t.Fatalf("after item 1: %q %v", after, ok)
+	}
+	if _, _, ok := r.f.AgentItem(grants.ForgetSibling(id)); ok {
+		t.Fatal("item 1's ID gave an item 2 line")
+	}
+}
